"""Record ONNX Runtime's answers for every fixture null can compile.

For each model, a few fixed-seed inputs are run through ONNX Runtime and the
inputs and outputs are stored in <model>.vectors. ctest then compiles the model
with nullc -o, runs the generated C on the same inputs, and compares (see
tests/e2e/run_vectors.c). The .vectors files are committed, so ctest needs no
Python; this script is only needed to regenerate them.

    pip install onnx onnxruntime numpy
    python tests/fixtures/e2e/make_e2e_vectors.py

.vectors format, little endian:
    "NULLVEC1"
    int32 trials, int32 num_inputs, int32 num_outputs
    int64 numel for each input, then for each output
    then, per trial: every input, then every output, as float32
"""
import os, struct

import numpy as np
import onnx
import onnxruntime as ort

HERE = os.path.dirname(os.path.abspath(__file__))
FIXTURES = os.path.dirname(HERE)

# every fixture null can compile today, with the batch fixed to 1
MODELS = [
    "relu", "linear", "mlp", "initializers_as_inputs",
    "pytorch/mlp__legacy_dyn", "pytorch/mlp__dynamo_dyn", "pytorch/mlp_view__legacy",
    "pytorch/lenet__legacy", "pytorch/lenet__dynamo",
]
TRIALS = 8


def shape_of(vi):
    return [d.dim_value if d.WhichOneof("value") == "dim_value" else 1 for d in vi.type.tensor_type.shape.dim]


for name in MODELS:
    path = os.path.join(FIXTURES, name + ".onnx")
    model = onnx.load(path)
    # onnxruntime only reads IR <= 13 while onnx 1.23 writes 14; only the stamp changes
    if model.ir_version > 10:
        model.ir_version = 10
    sess = ort.InferenceSession(model.SerializeToString(), providers=["CPUExecutionProvider"])
    inits = {t.name for t in model.graph.initializer}
    inputs = [vi for vi in model.graph.input if vi.name not in inits]
    shapes = [shape_of(vi) for vi in inputs]

    rng = np.random.default_rng(5010)
    trials = []
    for t in range(TRIALS):
        xs = []
        for s in shapes:
            if t == 0:
                x = np.zeros(s, np.float32)                               # all zeros
            elif t == 1:
                x = (rng.standard_normal(s) * 100).astype(np.float32)     # large magnitudes
            else:
                x = rng.standard_normal(s).astype(np.float32)
            xs.append(x)
        ys = sess.run(None, {vi.name: x for vi, x in zip(inputs, xs)})
        trials.append((xs, [np.asarray(y, np.float32) for y in ys]))

    xs0, ys0 = trials[0]
    out = os.path.join(HERE, name.replace("/", "__") + ".vectors")
    with open(out, "wb") as f:
        f.write(b"NULLVEC1")
        f.write(struct.pack("<iii", TRIALS, len(xs0), len(ys0)))
        for a in xs0 + ys0:
            f.write(struct.pack("<q", a.size))
        for xs, ys in trials:
            for a in xs + ys:
                f.write(np.ascontiguousarray(a, "<f4").tobytes())
    print(f"{os.path.basename(out):32s} {os.path.getsize(out):>7,d} bytes  "
          f"({TRIALS} trials, outputs {[list(y.shape) for y in ys0]})")

with open(os.path.join(HERE, "README.txt"), "w", newline="\n") as f:
    f.write(f"generated by make_e2e_vectors.py with onnxruntime {ort.__version__}, do not edit\n")
